/**
 * Markdown.Body: the parsed reply and its caret.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  derived,
  markdownEndsInProse,
  markdownShallowestHeading,
  parseMarkdown,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import { MarkdownBlocks, type MarkdownBlocksProps } from './MarkdownBlocks'
import { Text, type TextProps } from '../structure/Text'
import type { CitationSource } from './SourceList'

/** Markdown.Body: the parsed reply and its caret: the inputs it takes, by the React member's prop names. */
export interface MarkdownBodyProps {
  /**
   * The markdown received so far.
   */
  source: string
  size: 'sm' | 'md'
  sources: CitationSource[]
  streaming: boolean
}

/** Markdown.Body: the parsed reply and its caret. */
@Component({
  selector: 'pm-markdown-body',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [MarkdownBlocks, Text],
  // prettier-ignore
  template: `<pm-markdown-blocks
[blocks]="e1()"
[size]="e2()"
[sources]="e3()"
[shallowest]="e4()"
[caret]="e5()"
></pm-markdown-blocks>
@if (e6()) {<pm-text
[size]="e7()"
><!-- caret -->
<span
[attr.class]="e8()"
aria-hidden="true"
></span></pm-text>}`,
})
export class MarkdownBody {
  /**
   * The markdown received so far.
   */
  readonly source = input.required<MarkdownBodyProps['source']>()
  readonly size = input.required<MarkdownBodyProps['size']>()
  readonly sources = input.required<MarkdownBodyProps['sources']>()
  readonly streaming = input.required<MarkdownBodyProps['streaming']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      source: () => this.source(),
      size: () => this.size(),
      sources: () => this.sources(),
      streaming: () => this.streaming(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly blocks = derived(() =>
    parseMarkdown(this.$p.source, { citations: this.$p.sources.length }),
  )
  protected readonly shallowest = derived(() => markdownShallowestHeading(this.blocks.value))

  protected e1(): MarkdownBlocksProps['blocks'] {
    return this.blocks.value
  }

  protected e2(): MarkdownBlocksProps['size'] {
    return this.$p.size
  }

  protected e3(): MarkdownBlocksProps['sources'] {
    return this.$p.sources
  }

  protected e4(): MarkdownBlocksProps['shallowest'] {
    return this.shallowest.value
  }

  protected e5(): MarkdownBlocksProps['caret'] {
    return this.$p.streaming
  }

  protected e6() {
    return this.$p.streaming && !markdownEndsInProse(this.blocks.value)
  }

  protected e7(): TextProps['size'] {
    if (!(this.$p.streaming && !markdownEndsInProse(this.blocks.value))) return undefined as never
    return this.$p.size
  }

  protected e8() {
    if (!(this.$p.streaming && !markdownEndsInProse(this.blocks.value))) return undefined as never
    return styles.caret
  }
}
